gie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information und Kommunikation spielen in diesem Lernziel keine Rolle.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_struktur_funktion"],"basiskonzepte_sekundaer":["bk_evolutive_entwicklung","bk_stoff_energie_umwandlung"],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Atmungsorgane der fünf Klassen in einer Tabelle gegenüberstellen und Gemeinsamkeiten und Unterschiede markieren."},{"rang":2,"favorit":false,"methode":"Stationenlernen","beschreibung":"An Stationen Abbildungen oder Modelle von Kiemen, Haut und Lunge untersuchen und jeweils notieren, welche Tiere damit atmen."},{"rang":3,"favorit":false,"methode":"Kooperative Lernformen","beschreibung":"Mit Karten verschiedener Wirbeltiere in Partnerarbeit Vertreter dem passenden Atmungsorgan zuordnen und die Zuordnung begründen."}],"bezug_zum_lehrplan_kontext":"Eines der Vergleichsmerkmale der Wirbeltierklassen im Thema 2.2.8, neben Fortpflanzung, Körperbedeckung und Skelett.","moegliche_fehlvorstellungen":"Lernende gehen oft davon aus, dass Tiere im Wasser keinen Sauerstoff brauchen oder ihn aus dem Wasser selbst gewinnen.","evolutionsdidaktischer_impuls":null},"ki_entwurf":{"stand":"2026-11-01","hinweis":"KI-Entwurf (Claude), fachlich nicht geprüft","feedback":"01891c55"}}$j$::jsonb, updated_at = now() WHERE id = 'b496d374-795f-4cac-ac3a-1c6e62408c24' AND pro