UPDATE lpm_data_objects SET content = content || $j${"basiskonzeptbezug":[{"begruendung":"Die Angepasstheit an Wasser und Land ist ein Ergebnis der Stammesgeschichte; das Lernziel spricht diese aber nicht an.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":["Anpassung und Angepasstheit"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"}]},{"begruendung":"Vom Laich über die Larve bis zum erwachsenen Tier wird ein ganzer Entwicklungsweg mit Verwandlung beschrieben.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Metamorphose (vollständige/unvollständige Verwandlung)","Direkte und indirekte Entwicklung","Lebenszyklus und Entwicklungsphasen"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Metamorphose (vollständige/unvollständige Verwandlung)","taxonomyElementId":"99c41e90-ca7d-41d4-a0e4-18d3cf5f4752"},{"value":"Direkte und indirekte Entwicklung","taxonomyElementId":"eec14523-684d-46e0-94f6-de6f5e844b42"},{"value":"Lebenszyklus und Entwicklungsphasen","taxonomyElementId":"9a7ffac9-3344-468f-99b7-b52c1c002e88"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kiemen und Ruderschwanz im Wasser, Lunge, feuchte Haut und Gliedmaßen an Land: Bau und Lebensraum werden ausdrücklich verknüpft.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Morphologische und anatomische Angepasstheit"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Morphologische und anatomische Angepasstheit","taxonomyElementId":"66a61c3c-2ad8-44b1-8568-9c7fdc388e23"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Steueru