u keine Rolle.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_struktur_funktion"],"basiskonzepte_sekundaer":["bk_stoff_energie_umwandlung"],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Gestalterische/kreative Aufgaben","beschreibung":"Aus Netzstoffen, Rahmen und Auffangrinne ein eigenes Nebelfang-Modell bauen."},{"rang":2,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Eine Vermutung aufstellen, wie die Maschengröße die Wassermenge beeinflusst, das Modell mit mehreren Netzen testen und die aufgefangene Menge messen."},{"rang":3,"favorit":false,"methode":"Kooperative Lernformen","beschreibung":"In Teams jeweils eine Variante bauen, Messwerte zusammentragen und gemeinsam die effizienteste Variante begründen."}],"bezug_zum_lehrplan_kontext":"Fachpraktische Arbeit im Thema Bionik, die den Schritt vom biologischen Vorbild zum technischen Funktionsmodell praktisch erfahrbar macht.","moegliche_fehlvorstellungen":"Lernende erwarten oft, dass ein engmaschigeres Netz immer mehr Wasser liefert, und bedenken nicht, dass Tropfen auch im Netz hängen bleiben können.","evolutionsdidaktischer_impuls":null},"ki_entwurf":{"stand":"2026-11-01","hinweis":"KI-Entwurf (Claude), fachlich nicht geprüft","feedback":"01891c55"}}$j$::jsonb, updated_at = now() WHERE id = '54238a78-3402-405d-b942-cefd5fae5f00' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND NOT (content ? 'basiskonzeptbezug');
