UPDATE lpm_data_objects SET content = content || $j${"basiskonzeptbezug":[{"begruendung":"Die Flügeldecken lassen sich als Angepasstheit des Käfers an seinen trockenen Lebensraum verstehen, die das Lernziel aber nur als biologisches Vorbild behandelt.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":["Anpassung und Angepasstheit"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Anpassung und Angepasstheit","taxonomyElementId":"009a7d9b-c6f7-4df7-aa51-c1be91669a5b"}]},{"begruendung":"Es geht um den Bau des Käfers. Seine Entwicklung ist nicht Thema.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Höcker und Rillen auf den Flügeldecken sind Bauelemente, deren Form und Oberflächeneigenschaft direkt mit der Funktion (Kondensieren und Transportieren von Wasser) verknüpft wird.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Morphologische und anatomische Angepasstheit","Oberflächenvergrößerung"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Morphologische und anatomische Angepasstheit","taxonomyElementId":"66a61c3c-2ad8-44b1-8568-9c7fdc388e23"},{"value":"Oberflächenvergrößerung","taxonomyElementId":"2c181338-9db5-4a67-9cc2-e4e8ec93d3c8"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Eine Steuerung oder Regelung ist im Lernziel nicht angesprochen.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Käfer gewinnt Wasser durch Kondensation von Wasserdampf und leitet es zum Mund, also eine Stoffaufnahme aus der Umgebung.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Informationsverarbeitung spielt in diesem Beispiel keine Rolle.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_struktur_funktion"],"basiskonzepte_sekundaer":["bk_evolutive_entwicklung","bk_stoff_energie_umwandlung"],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Recherche","beschreibung":"Informationen zu Lebensraum und Körperbau des Nebeltrinkerkäfers sammeln und in einem Steckbrief ordnen."},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Mit wasserliebenden und wasserabweisenden Flächen (z. B. Folie, Höcker aus Klebepunkten) nachbauen, wie Tröpfchen sich sammeln und abfließen."},{"rang":3,"favorit":false,"methode":"Konzeptuelles Lernen","beschreibung":"Vorbild und Prinzip getrennt in einer Tabelle festhalten und formulieren, welche Eigenschaft welche Funktion ermöglicht."}],"bezug_zum_lehrplan_kontext":"Erster Schritt der Bionik-Schrittfolge am Beispiel Nebeltrinkerkäfer, an den das Vergleichen mit der Technik und das Übertragen auf Nebelkollektoren anschließen.","moegliche_fehlvorstellungen":"Lernende denken oft, der Käfer „trinke“ den Nebel direkt, statt zu erkennen, dass Tröpfchen an den Höckern kondensieren und über Rillen zum Mund laufen.","evolutionsdidaktischer_impuls":"Die Frage, warum Käfer in nebelreichen Trockengebieten solche Flügeldecken haben, lässt sich als 