UPDATE lpm_data_objects SET content = content || $j${"basiskonzeptbezug":[{"begruendung":"Kein Bezug zu Abstammung, Variation oder Anpassung.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Es geht um unbelebte Stoffe. Entwicklung von Lebewesen kommt nicht vor.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Teilchenmodell erklärt Stoffe. Bau und Leistung von Organen sind kein Thema.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Eine Steuerung oder Regelung kommt in diesem Lernziel nicht vor.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Lernenden erklären, wie sich Zucker und Wasser als zwei Reinstoffe zu einem Gemisch verbinden. Das ist die stoffliche Grundlage für spätere Betrachtungen von Lösungsvorgängen in Lebewesen. Es ist allerdings ein physikalischer Vorgang ohne Stoffumwandlung.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information oder Kommunikation spielt bei der Lösung von Zucker in Wasser keine Rolle.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"basiskonzepte_sekundaer":[],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Zucker in Wasser lösen, Geschmack und Aussehen vergleichen und festhalten, dass Zucker nach dem Lösen noch vorhanden ist."},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Mit zwei Sorten verschiedenfarbiger Kugeln die Zucker-Wasser-Lösung als Modell legen und zeichnen."},{"rang":3,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Das Kugelmodell der Lösung mit einem Gemisch aus Erbsen und Reis vergleichen und die Grenzen dieses Vergleichs benennen."}],"bezug_zum_lehrplan_kontext":"Überträgt das Kugelteilchenmodell der Stoffe auf Gemische, hier am Beispiel der Zucker-Wasser-Lösung.","moegliche_fehlvorstellungen":"Viele Lernende denken, der Zucker sei nach dem Lösen verschwunden oder zu Wasser geworden.","evolutionsdidaktischer_impuls":null},"ki_entwurf":{"stand":"2026-11-01","hinweis":"KI-Entwurf (Claude), fachlich nicht geprüft","feedback":"01891c55"}}$j$::jsonb, updated_at = now() WHERE id = 'a868f6c8-9909-4503-b35f-76cd38607997' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND NOT (content ? 'basiskonzeptbezug');
