:"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"basiskonzepte_sekundaer":[],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Ein Kugelmodell (Kugeln in einer flachen Schale) bauen und durch Schütteln die Teilchenbewegung anschaulich machen."},{"rang":2,"favorit":false,"methode":"Digitale Medien","beschreibung":"Eine Teilchensimulation am Tablet oder Computer ansehen und beschreiben, wie sich die Teilchen bewegen."},{"rang":3,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Das Kugelmodell mit der Ausbreitung eines Tintentropfens im Wasser vergleichen und prüfen, was das Modell erklärt und was es vereinfacht."}],"bezug_zum_lehrplan_kontext":"Führt das Teilchenmodell im Abschnitt Stoffe und ihre Eigenschaften ein, auf dem die Lernziele zu Aggregatzuständen und Gemischen aufbauen.","moegliche_fehlvorstellungen":"Lernende vermuten häufig, zwischen den Teilchen befinde sich Luft oder ein anderer Stoff statt leerem Raum.","evolutionsdidaktischer_impuls":null},"ki_entwurf":{"stand":"2026-11-01","hinweis":"KI-Entwurf (Claude), fachlich nicht geprüft","feedback":"01891c55"}}$j$::jsonb, updated_at = now() WHERE id = '3ee0353a-78a1-4091-a10b-6f32884c98ef' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND NOT (content ? 'basiskonzeptbezug');
UPDATE lpm_data_objects SET content = content || $j${"basiskonzeptbezug":[{"begruendung":"Das Lernziel spricht keine Abstammung oder Anpassung an.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Es geht um Stofftransport in der erwachsenen Pflanze. Ihre Entwicklung ist kein Thema.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Die Leistung der Sprossachse, Wasser zu transportieren, wird mit ihrem Bau aus dünnen Röhren und der Kapillarität erklärt. Das ist ein unmittelbares Beispiel für den Zusammenhang von Struktur und Funktion.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Morphologische und anatomische Angepasstheit"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Morphologische und anatomische Angepasstheit","taxonomyElementId":"66a61c3c-2ad8-44b1-8568-9c7fdc388e23"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Wassertransport wird hier als physikalischer Vorgang beschrieben, ohne Steuerung oder Regelung.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Wasser, Mineralsalze und Kohlenstoffdioxid gelangen aus der Umwelt in die Pflanze und zu den Laubblättern. Der Stoffaustausch mit der Umwelt steht hier im Hintergrund.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Stoffaustausch mit der Umwelt"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Stoffaustausch mit der Umwelt","taxonomyElementId":"fea929f6-568f-4630-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Information oder Kommunikation kommt im Lernziel nicht vor.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_struktur_funktion"],"basiskonzepte_sekundaer":["bk_stoff_energie_umwandlung"],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Forschendes Lernen","beschreibung":"Einen Pflanzenstängel in gefärbtes Wasser stellen, nach einigen Stunden Querschnitte betrachten und aus der Färbung auf die Leitungsbahnen schließen."},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Dünne Glasröhrchen in gefärbtes Wasser tauchen und beobachten, wie das Wasser aufsteigt."},{"rang":3,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Das Aufsteigen in Trinkhalmen unterschiedlicher Dicke vergleichen und auf die Röhren der Sprossachse übertragen."}],"bezug_zum_lehrplan_kontext":"Wendet die Kapillarität auf die Pflanze an und beschreibt den Weg der Stoffe bis in die Laubblätter, in denen die Ernährung der Samenpflanzen weitergeführt wird.","moegliche_fehlvorstellungen":"Häufig wird angenommen, Pflanzen nähmen ihre Nahrung als fertige Stoffe aus dem Boden auf.","evolutionsdidaktischer_impuls":null},"ki_entwurf":{"stand":"2026-11-01","hinweis":"KI-Entwurf (Claude), fachlich nicht geprüft","feedback":"01891c55"}}$j$::jsonb, updated_at = now() WHERE id = '7c671821-9a90-46ce-b5e9-87a82741533e' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND NOT (content ? 'basiskonzeptbez