-8de4-84f4aa700f63"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Kein Bezug zu Information oder Kommunikation.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"basiskonzepte_sekundaer":["bk_struktur_funktion"],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Mit einem Schlauchmodell, das einen Darm darstellt, zeigen, dass kleine Bausteine hindurchtreten und größere zurückbleiben."},{"rang":2,"favorit":false,"methode":"Gestalterische/kreative Aufgaben","beschreibung":"Den Weg der Nährstoffe vom Darm über das Blut zu den Körperteilen als Karte oder Poster zeichnen."},{"rang":3,"favorit":false,"methode":"Digitale Medien","beschreibung":"Eine Animation zum Weg der Nährstoffe ansehen und die Stationen mit eigenen Worten nacherzählen."}],"bezug_zum_lehrplan_kontext":"Schließt an Zerkleinerung und Zerlegung der Nahrung an und beschreibt, wie die Bausteine ins Blut gelangen, bevor sie im Körper verwendet werden.","moegliche_fehlvorstellungen":"Häufig wird angenommen, die Nahrung wandere als Ganzes unverändert ins Blut.","evolutionsdidaktischer_impuls":null},"ki_entwurf":{"stand":"2026-11-01","hinweis":"KI-Entwurf (Claude), fachlich nicht geprüft","feedback":"01891c55"}}$j$::jsonb, updated_at = now() WHERE id = '1d60b2d6-b523-46ef-a334-cd8d7914a295' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND NOT (content ? 'basiskonzeptbezug');
