UPDATE lpm_data_objects SET content = content || $j${"basiskonzeptbezug":[{"begruendung":"Das Lernziel beschreibt den Ablauf und spricht Variation oder Abstammung nicht an.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Befruchtung und Fruchtbildung sind zentrale Schritte der Fortpflanzung und der Entwicklung einer Samenpflanze vom Blütenstadium zur Frucht mit Samen.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Reproduktion/Fortpflanzung","Lebenszyklus und Entwicklungsphasen"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Reproduktion/Fortpflanzung","taxonomyElementId":"d1597cd6-5648-49bc-9ad2-9f27f9f43bc5"},{"value":"Lebenszyklus und Entwicklungsphasen","taxonomyElementId":"9a7ffac9-3344-468f-99b7-b52c1c002e88"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Bau von Samen- und Eizelle steht nicht im Mittelpunkt, es geht um den Ablauf.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Steuerung oder Regelung wird im Lernziel nicht angesprochen.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- und Energieumwandlungen werden bei der Befruchtung nicht thematisiert.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Genetische Information wird im Lernziel nicht genannt.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_individuelle_entwicklung"],"basiskonzepte_sekundaer":[],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Den Weg des Pollenschlauchs und die Verschmelzung von Samenzelle und Eizelle an einem Schema oder Legemodell Schritt für Schritt nachstellen."},{"rang":2,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Blüten, unreife und reife Früchte (z. B. Apfel, Erbse) aufschneiden und beobachten, wo die Samen liegen."},{"rang":3,"favorit":false,"methode":"Gestalterische/kreative Aufgaben","beschreibung":"Eine Bildfolge oder einen Comic von der Blüte über die Befruchtung bis zur Frucht zeichnen und beschriften."}],"bezug_zum_lehrplan_kontext":"Schließt im Unterthema Fortpflanzung und Entwicklung der Samenpflanzen an die Bestäubung an, denn erst nach dem Pollentransport kann die Befruchtung stattfinden.","moegliche_fehlvorstellungen":"Bestäubung und Befruchtung werden oft gleichgesetzt, obwohl die Bestäubung nur die Übertragung des Pollens ist.","evolutionsdidaktischer_impuls":null},"ki_entwurf":{"stand":"2026-11-01","hinweis":"KI-Entwurf (Claude), fachlich nicht geprüft","feedback":"01891c55"}}$j$::jsonb, updated_at = now() WHERE id = 'a95d79eb-4ea6-482e-b16f-c45948c925e0' AND project_id = '1b121ef2-96c2-43f7-aa2b-0e07b8de114a' AND NOT (content ? 'basiskonzeptbezug');
