er keine Rolle.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_stoff_energie_umwandlung"],"basiskonzepte_sekundaer":[],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Zucker in Wasser lösen, Geschmack und Aussehen vergleichen und festhalten, dass Zucker nach dem Lösen noch vorhanden ist."},{"rang":2,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Mit zwei Sorten verschiedenfarbiger Kugeln die Zucker-Wasser-Lösung als Modell legen und zeichnen."},{"rang":3,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Das Kugelmodell der Lösung mit einem Gemisch aus Erbsen und Reis vergleichen und die Grenzen dieses Vergleichs benennen."}],"bezug_zum_lehrplan_kontext":"Überträgt das Kugelteilchenmodell der Stoffe auf Gemische, hier am Beispiel der Zucker-Wasser-Lösung.","moegliche_fehlvorstellungen":"Viele Lernende denken, der Zucker sei nach dem Lösen verschwunden oder zu Wasser geworden.","evolutionsdidaktischer_impuls":null},"ki_entwurf":{"stand":"2026-11-01","hinweis":"KI-Entwurf (Claude), fachlich nicht geprüft","feedback":"01891c55"}}$j$::jsonb, updated_at = now() WHERE id = '7567766b-ec0d-45a9-a8bc-2ca80cef68d8' AND project_id = (SELECT id FROM projects WHERE slug = 'evomentor-thuringia-sandbox') AND NOT (content ? 'basiskonzeptbezug');
