UPDATE lpm_data_objects SET content = content || $j${"basiskonzeptbezug":[{"begruendung":"Lebensgemeinschaften werden genannt, Evolution oder Anpassung aber nicht angesprochen.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Es geht um die Rolle von Pflanzen im Lebensraum. Ihre Entwicklung ist kein Thema.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Bau und Leistung von Pflanzenorganen werden im Lernziel nicht behandelt.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Steuerung oder Regelung ist in diesem Lernziel nicht angesprochen.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Pflanzen sind Nahrungsgrundlage für Tiere und stellen Sauerstoff bereit. Damit sind Stoff- und Energiefluss in Lebensgemeinschaften unmittelbar angesprochen.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Energiefluss durch Nahrungsketten"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Energiefluss durch Nahrungsketten","taxonomyElementId":"a7e5d1d8-b3ff-42f0-a134-cf5955fca65f"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendu