UPDATE lpm_data_objects SET content = content || $j${"basiskonzeptbezug":[{"begruendung":"Das Lernziel beschreibt den Ablauf und spricht Variation oder Abstammung nicht an.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Befruchtung und Fruchtbildung sind zentrale Schritte der Fortpflanzung und der Entwicklung einer Samenpflanze vom Blütenstadium zur Frucht mit Samen.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Reproduktion/Fortpflanzung","Lebenszyklus und Entwicklungsphasen"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Reproduktion/Fortpflanzung","taxonomyElementId":"32625bcc-f4e6-4b0d-945d-066d43c64b6c"},{"value":"Lebenszyklus und Entwicklungsphasen","taxonomyElementId":"50f84e4f-a661-4dd4-8139-b7228c4c92a0"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Der Bau von Samen- und Eizelle steht nicht im Mittelpunkt, es geht um den Ablauf.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Steuerung oder Regelung wird im Lernziel nicht angesprochen.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- und Energieumwandlungen werden bei der Befruchtung nicht thematisiert.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Genetische Information wird im Lernziel nicht genannt.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_individuelle_entwicklung"],"basiskonzepte_sekundaer":[],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Den Weg des Pollenschlauchs und die Verschmelzung von Samenzelle und Eizelle an einem Schema oder Legemodell Schritt für Schritt nachstellen."},{"rang":2,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Blüten, unreife und reife Früchte (z. B. Apfel, Erbse) aufschneiden und beobachten, wo die Samen liegen."},{"rang":3,"favorit":false,"methode":"Gestalterische/kreative Aufgaben","beschreibung":"Eine Bildfolge oder einen Comic von der Blüte über die Befruchtung bis zur Frucht zeichnen und beschriften."}],"bezug_zum_lehrplan_kontext":"Schließt im Unterthema Fortpflanzung und Entwicklung der Samenpflanzen an die Bestäubung an, denn erst nach dem Pollentransport kann die Befruchtung stattfinden.","moegliche_fehlvorstellungen":"Bestäubung und Befruchtung werden oft gleichgesetzt, obwohl die Bestäubung nur die Übertragung des Pollens ist.","evolutionsdidaktischer_impuls":null},"ki_entwurf":{"stand":"2026-11-01","hinweis":"KI-Entwurf (Claude), fachlich nicht geprüft","feedback":"01891c55"}}$j$::jsonb, updated_at = now() WHERE id = 'a0c41849-c821-4272-8c75-79b0ccce71e0' AND project_id = (SELECT id FROM projects WHERE slug = 'evomentor-thuringia-sandbox') AND NOT (content ? 'basiskonzeptbezug');
