UPDATE lpm_data_objects SET content = content || $j${"basiskonzeptbezug":[{"begruendung":"Die unterschiedlichen Blütenformen sind ein Beispiel für Angepasstheit als Ergebnis von Evolution. Der Begriff selbst fällt im Lernziel aber nicht.","basiskonzept_id":"bk_evolutive_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":["Anpassung und Angepasstheit"],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[{"value":"Anpassung und Angepasstheit","taxonomyElementId":"51f19e96-51c0-4412-8ac4-5735ae624a33"}]},{"begruendung":"Die Bestäubung ist ein Schritt der Fortpflanzung der Samenpflanzen und damit Teil ihrer Entwicklung.","basiskonzept_id":"bk_individuelle_entwicklung","relevanz_beurteilung":2,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Reproduktion/Fortpflanzung"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Reproduktion/Fortpflanzung","taxonomyElementId":"32625bcc-f4e6-4b0d-945d-066d43c64b6c"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Das Lernziel verlangt ausdrücklich, den Bau von Blüten (Staubblatt, Narbe, Blütenform) mit der Funktion Bestäubung durch Wind oder Insekten zu verknüpfen.","basiskonzept_id":"bk_struktur_funktion","relevanz_beurteilung":3,"relevante_teilkonzepte":[],"relevante_unterkonzepte":["Morphologische und anatomische Angepasstheit"],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[{"value":"Morphologische und anatomische Angepasstheit","taxonomyElementId":"d50879ab-c189-4bf6-a457-194bc217f14a"}],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Steuerung oder Regelung ist nicht Gegenstand des Lernziels.","basiskonzept_id":"bk_steuerung_regelung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Stoff- und Energieumwandlungen stehen bei der Bestäubung nicht im Mittelpunkt.","basiskonzept_id":"bk_stoff_energie_umwandlung","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]},{"begruendung":"Signale wie Duft oder Farbe werden im Lernziel nicht genannt.","basiskonzept_id":"bk_information_kommunikation","relevanz_beurteilung":1,"relevante_teilkonzepte":[],"relevante_unterkonzepte":[],"relevante_evolutionskonzepte":[],"relevante_unterkonzepte_taxonomie":[],"relevante_evolutionskonzepte_taxonomie":[]}],"basiskonzepte_primaer":["bk_struktur_funktion"],"basiskonzepte_sekundaer":["bk_evolutive_entwicklung","bk_individuelle_entwicklung"],"didaktische_strategien":{"top3_methoden":[{"rang":1,"favorit":false,"methode":"Erfahrungs-/handlungsorientiertes Lernen","beschreibung":"Windblütige und insektenblütige Blüten (z. B. Gras, Kirsche) mit der Lupe untersuchen und Staubblatt, Narbe und Blütenform skizzieren."},{"rang":2,"favorit":false,"methode":"Analogien und Vergleiche","beschreibung":"Eine Tabelle zu Wind- und Insektenblüten anlegen und Bau und Bestäubungsart einander zuordnen."},{"rang":3,"favorit":false,"methode":"Modelle und Simulationen","beschreibung":"Mit Pollenersatz (z. B. Mehl) und Pinsel oder Fön nachstellen, wie Pollen zur Narbe gelangen kann."}],"bezug_zum_lehrplan_kontext":"Steht im Unterthema Fortpflanzung und Entwicklung der Samenpflanzen vor der Befruchtung und Fruchtbildung und liefert den Blütenbau, auf den diese aufbauen.","moegliche_fehlvorstellungen":"Lernende denken oft, Pflanzen bauten ihre Blüten absichtlich so, um Insekten anzulocken.","evolutionsdidaktischer_impuls":"Blüten mit Merkmalen, die ihre Bestäubung begünstigen, bildeten über viele Generationen mehr Samen, sodass sich solche Merkmale in Pflanzenpopulationen ausbreiteten."},"ki_entwurf":{"stand":"2026-11-01","hinweis":"KI-Entwurf