DO $$
DECLARE drafted integer;
BEGIN
  SELECT count(*) INTO drafted FROM lpm_data_objects o
  WHERE o.project_id IN (SELECT id FROM projects WHERE slug IN ('evomentor-thuringia', 'evomentor-thuringia-sandbox'))
    AND o.grade_band = '5/6' AND o.status = 'accepted' AND o.content ? 'ki_entwurf' AND o.content -> 'ki_entwurf' ->> 'feedback' = '01891c55';
  IF drafted <> 258 THEN
    RAISE EXCEPTION 'migration 214: expected 258 drafted goals (129 per space), found %', drafted;
  END IF;
END $$;
